// Keys are fetched by `kid` and cached; rotation works without a redeploy
const JWKS = createRemoteJWKSet(new URL('https://auth.example.com/.well-known/jwks.json'));

export async function verifyAccessToken(token: string) {
  const { payload } = await jwtVerify(token, JWKS, {
    algorithms: ['RS256'],            // never trust the alg header
    issuer: 'https://auth.example.com/',
    audience: 'api.example.com',      // a token for another API is rejected
    clockTolerance: '30s',
  });
  // jwtVerify already rejects expired tokens (exp) and not-yet-valid ones (nbf)
  return { userId: payload.sub!, scope: String(payload.scope ?? '') };
}

