import * as client from 'openid-client';

const config = await client.discovery(
  new URL('https://accounts.google.com'),
  process.env.GOOGLE_CLIENT_ID!,
  process.env.GOOGLE_CLIENT_SECRET!,
);

// Login: create verifier + state, keep them in the server session
export async function startLogin(session: Session) {
  session.pkceVerifier = client.randomPKCECodeVerifier();
  session.oauthState = client.randomState();
  return client.buildAuthorizationUrl(config, {
    redirect_uri: 'https://app.example.com/auth/callback', // exact, from config
    scope: 'openid email profile',
    code_challenge: await client.calculatePKCECodeChallenge(session.pkceVerifier),
    code_challenge_method: 'S256',
    state: session.oauthState,
  });
}

// Callback: the library checks state, exchanges the code and validates the ID token
export async function finishLogin(session: Session, currentUrl: URL) {
  const tokens = await client.authorizationCodeGrant(config, currentUrl, {
    pkceCodeVerifier: session.pkceVerifier,
    expectedState: session.oauthState,
  });
  const claims = tokens.claims()!; // verified iss, aud, exp
  const user = await upsertUserByIssuerAndSub(claims.iss, claims.sub);
  await session.regenerate({ userId: user.id }); // your own session, new ID
}

