import * as argon2 from 'argon2'; // node-argon2 0.4x, Node 22+

// Target parameters. needsRehash() flags ANY difference from these values,
// so raise them here and users are upgraded at their next login.
const PARAMS: argon2.HashOptions = {
  type: argon2.argon2id,
  memoryCost: 19456, // KiB = 19 MiB (OWASP minimum)
  timeCost: 2,
  parallelism: 1,
};

// Computed once, so unknown emails take as long as known ones
const DUMMY_HASH = await argon2.hash('timing-equaliser', PARAMS);

export function hashPassword(password: string) {
  // Random salt is generated and stored in the PHC string:
  // "$argon2id$v=19$m=19456,p=1,t=2$<salt>$<hash>"
  return argon2.hash(password, PARAMS);
}

export async function login(email: string, password: string) {
  const user = await db.user.findUnique({ where: { email } });
  const ok = await argon2.verify(user?.passwordHash ?? DUMMY_HASH, password);
  if (!user || !ok) return null;

  if (argon2.needsRehash(user.passwordHash, PARAMS)) {
    const passwordHash = await hashPassword(password);
    await db.user.update({ where: { id: user.id }, data: { passwordHash } });
  }
  return user;
}

