import type { Request, Response, NextFunction } from 'express';

const ALLOWED_ORIGINS = new Set(['https://app.example.com']);
const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export function csrfGuard(req: Request, res: Response, next: NextFunction) {
  if (SAFE_METHODS.has(req.method)) return next(); // GET must never change state

  // 1. Fetch Metadata: the browser says where the request came from
  const site = req.get('Sec-Fetch-Site');
  if (site && site !== 'same-origin' && site !== 'none') {
    return res.status(403).json({ error: 'Cross-site request blocked' });
  }

  // 2. Origin check as a fallback for clients without Sec-Fetch-Site
  const origin = req.get('Origin');
  if (origin && !ALLOWED_ORIGINS.has(origin)) {
    return res.status(403).json({ error: 'Bad origin' });
  }

  // 3. JSON APIs: refuse form and text/plain bodies that a plain HTML form can send
  if (req.get('Content-Type') && !req.is('application/json')) return res.status(415).end();
  next();
}

