import crypto from 'node:crypto';

// Keys come from a KMS / secret manager, never from source code
const KEYS: Record<string, Buffer> = { v2: loadKey('v2'), v1: loadKey('v1') };
const CURRENT = 'v2';

export function encrypt(plaintext: string, aad: string): string {
  const iv = crypto.randomBytes(12); // fresh 96-bit IV every time
  const cipher = crypto.createCipheriv('aes-256-gcm', KEYS[CURRENT], iv);
  cipher.setAAD(Buffer.from(aad)); // e.g. `user:42:google_token`
  const ct = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [CURRENT, iv, tag, ct].map(p => (typeof p === 'string' ? p : p.toString('base64url'))).join('.');
}

export function decrypt(stored: string, aad: string): string {
  const [version, iv, tag, ct] = stored.split('.');
  const decipher = crypto.createDecipheriv('aes-256-gcm', KEYS[version], Buffer.from(iv, 'base64url'));
  decipher.setAAD(Buffer.from(aad));
  decipher.setAuthTag(Buffer.from(tag, 'base64url'));
  // Throws if the data, tag or AAD was changed
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64url')), decipher.final()]).toString('utf8');
}

let counter = 0;

export function encrypt(plaintext: string) {
  const iv = Buffer.alloc(12);
  iv.writeUInt32BE(counter++, 8); // unique IV per message
  const cipher = crypto.createCipheriv('aes-256-gcm', KEY, iv);
  const ct = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  return Buffer.concat([iv, cipher.getAuthTag(), ct]).toString('base64');
}

