import express from 'express';

const SECRETS = [process.env.WEBHOOK_SECRET!, process.env.WEBHOOK_SECRET_OLD].filter(Boolean) as string[];
const TOLERANCE_S = 300;

function validSignature(raw: Buffer, timestamp: string, header: string): boolean {
  const given = Buffer.from(header.replace(/^sha256=/, ''), 'hex');
  return SECRETS.some(secret => {
    const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.`).update(raw).digest();
    return given.length === expected.length && crypto.timingSafeEqual(given, expected);
  });
}

